public class CaseTransformerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String call(String input) {
        try {
            java.io.StringWriter out = new java.io.StringWriter();
            CaseTransformer.upperCase(new java.io.StringReader(input), out);
            return out.toString();
        } catch (Exception e) {
            return "threw " + e.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("simple words", "HELLO WORLD", call("hello world"));
        check("mixed case and symbols", "ABC1! X", call("AbC1! x"));
        check("already upper case", "JAVA", call("JAVA"));
        check("digits and operators unchanged", "42 + 8", call("42 + 8"));
        check("newlines preserved", "A\nB", call("a\nb"));
        check("empty input writes nothing", "", call(""));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

