public class CaseTransformer {

    public static void upperCase(java.io.Reader in, java.io.Writer out)
            throws java.io.IOException {
        int c;
        while ((c = in.read()) != -1) {
            out.write(Character.toUpperCase((char) c));
        }
    }
}
